"""Independently recover the write-size choices and archive all measurements."""

import gzip
import hashlib
import json
import math
import statistics
import sys
from pathlib import Path

from audit_kl_panels import check
from audit_whole_model_replay import digest, read, verified_receipt


ARMS = ("exact", "compressed", "rotated")
SCALES = (0.03125, 0.0625, 0.125, 0.25, 0.5, 1.0)
FAMILIES = ("packing", "register")
FIELDS = {"fixed_support_kl", "dynamic_js", "dynamic_tv", "support_changed",
          "removed_baseline_mass", "added_alternative_mass"}


def seed(name):
    tag = f"qwen.kl.{name}.L1".encode()
    return (811041 ^ int.from_bytes(hashlib.blake2b(tag, digest_size=8).digest(), "little")) % (2**63)


def inspect_panel(name, panel, evidence, labels):
    assert evidence["batch_seed"] == seed(name)
    assert len(evidence["trajectories"]) == 4 * len(panel) == 32
    expected = {}
    for index, item in enumerate(evidence["trajectories"]):
        prompt = panel[index // 4]
        assert item["question"] == prompt["id"] and item["sample"] == index % 4
        n = item["lexical_tokens"]
        assert 0 <= n <= 512 and len(item["action_ids"]) == n + int(item["emitted_eos"])
        assert item["emitted_eos"] or n == 512
        if item["emitted_eos"]:
            assert item["action_ids"][-1] in (151645, 151643)
        steps = [*range(31, n, 32)] + ([n] if item["emitted_eos"] else [])
        for step in steps:
            expected[index, step] = (
                prompt["id"], item["sample"], prompt["family"], "eos" if step == n else "content", item["action_ids"][step],
            )
    repo_values = {label: {family: [] for family in FAMILIES} for label in labels}
    combined = evidence["measurements"]
    for row in combined:
        key = row["row"], row["step"]
        assert expected.pop(key) == (row["question"], row["sample"], row["family"], row["kind"], row["action"])
        assert set(row) == {*labels, "row", "question", "sample", "family", "step", "kind", "action"}
        for label in labels:
            measure = row[label]
            assert set(measure) == FIELDS
            kl, js, tv = (measure[k] for k in ("fixed_support_kl", "dynamic_js", "dynamic_tv"))
            assert math.isfinite(kl) and 0 <= kl and 0 <= js <= math.log(2) + 1e-12
            assert 0 <= tv <= 1 + 1e-12 and tv * tv <= 2 * js + 1e-12
            assert isinstance(measure["support_changed"], bool)
            assert 0 <= measure["removed_baseline_mass"] <= tv + 1e-12
            assert 0 <= measure["added_alternative_mass"] <= tv + 1e-12
            if not measure["support_changed"]:
                assert not (measure["removed_baseline_mass"] or measure["added_alternative_mass"])
            repo_values[label][row["family"]].append(measure)
    assert not expected
    return {label: {wording: {"prefixes": len(samples),
                             "mean_kl": statistics.fmean(row["fixed_support_kl"] for row in samples),
                             "mean_js": statistics.fmean(row["dynamic_js"] for row in samples),
                             "mean_tv": statistics.fmean(row["dynamic_tv"] for row in samples),
                             "support_changes": sum(row["support_changed"] for row in samples)}
                    for wording, samples in values.items()} for label, values in repo_values.items()}


def matching_summary(native, independent):
    assert set(native) == set(independent)
    for label, values in independent.items():
        for wording, row in values.items():
            for name, expected in row.items():
                assert math.isclose(native[label][wording][name], expected, rel_tol=0, abs_tol=1e-13)


def gate(strata):
    return all(row["mean_kl"] <= 0.005 and row["mean_js"] <= 0.00125 for row in strata.values())


def inspect(work):
    sealed = work / "panels.json"
    panel_audit = check(sealed, work / "ladder.json.gz")
    raw = read(work / "calibration.json")
    adaptation = work / "adaptation.json"
    assert raw["adapted_sha256"] == digest(adaptation)
    earlier = read(adaptation)
    assert raw["candidate_sha256"] == earlier["candidate_writes"]["sha256"]
    assert raw["checkpoint_sha256"] == earlier["checkpoint_sha256"]
    assert raw["panel_sha256"] == panel_audit["panel_sha256"]
    assert raw["fixed_support_kl_ceiling"] == .005 and raw["dynamic_js_ceiling"] == .00125
    assert raw["seed"] == 811041 and raw["stride"] == 32 and tuple(raw["scales"]) == SCALES
    panels = read(sealed)["panels"]
    labels = [f"{arm}@{scale}" for arm in ARMS for scale in SCALES]
    cal = inspect_panel("calibration", panels["calibration"], raw["calibration"], labels)
    matching_summary(raw["calibration_summary"], cal)
    choice = {}
    for arm in ARMS:
        for scale in SCALES:
            if not gate(cal[f"{arm}@{scale}"]):
                break
            choice[arm] = scale
    assert choice == raw["chosen_scales"]
    result = {}
    if len(choice) == len(ARMS):
        labels = [f"{arm}@{value}" for arm, value in choice.items()]
        result = inspect_panel("verification", panels["verification"], raw["verification"], labels)
    else:
        assert raw["verification"] is None
    matching_summary(raw["verification_summary"], result)
    tested = {variant: gate(values) for variant, values in result.items()}
    qualified = len(tested) == 3 and all(tested.values())
    assert qualified == raw["qualified"]
    return {"panel_integrity": panel_audit, "calibration_prefixes": len(raw["calibration"]["measurements"]),
            "verification_prefixes": len(raw["verification"]["measurements"]) if result else 0,
            "selection": choice, "verification_gates": tested, "qualified": qualified,
            "sampling_support_verified": True}


def publish(work, registration, source_hash, output):
    audit = inspect(work)
    assert audit == read(work / "calibration_audit.json")
    raw_path, panel_path = work / "calibration.json", work / "panels.json"
    raw = read(raw_path)
    artifact = {"study": raw, "panels": read(panel_path), "audit": audit}
    encoded = gzip.compress(json.dumps(artifact, sort_keys=True, separators=(",", ":"), allow_nan=False).encode(),
                            compresslevel=9, mtime=0)
    assert json.loads(gzip.decompress(encoded)) == artifact
    paths = ("calibrate_qwen_kl.py", "audit_qwen_kl.py", "kl_panels.py", "audit_kl_panels.py", "kl_metric_fixture.py",
             "ladder_panels.py", "qwen_external.py", "run_ladder.py")
    sources = {name: {"sha256": digest(work / name), "content": (work / name).read_text(encoding="utf-8")} for name in paths}
    assert sources[paths[0]]["sha256"] == source_hash
    receipts = {name: verified_receipt(work / (name + ".json")) for name in
                ("qwen-kl-seal-panels", "qwen-kl-independent-panel-audit", "qwen-kl-masked-metric-fixture",
                 "qwen-kl-independent-verification", "qwen-kl-independent-result-audit")}
    public = {key: value for key, value in raw.items() if key not in ("calibration", "verification")}
    public.update({"audit": audit, "dsr": receipts, "sources": sources, "registered_protocol": registration,
                   "archive_sha256": hashlib.sha256(encoded).hexdigest(), "raw_sha256": digest(raw_path)})
    with output.with_suffix(".json.gz").open("xb") as stream:
        stream.write(encoded)
    with output.open("x", encoding="utf-8") as stream:
        json.dump(public, stream, sort_keys=True, indent=2, allow_nan=False)
        stream.write("\n")


if __name__ == "__main__":
    if not __debug__:
        raise RuntimeError("The calibration audit requires Python assertions.")
    if sys.argv[1] == "publish":
        publish(Path(sys.argv[2]), sys.argv[3], sys.argv[4], Path(sys.argv[5]))
    else:
        root = Path(sys.argv[1])
        checked = inspect(root)
        with (root / "calibration_audit.json").open("x", encoding="utf-8") as stream:
            json.dump(checked, stream, sort_keys=True, indent=2, allow_nan=False)
            stream.write("\n")

