"""Seal disjoint arithmetic calibration, verification and transfer prompts."""

import gzip
import hashlib
import json
import random
import sys
from pathlib import Path

from ladder_panels import execute, operations, render


SEED = 811040
LAYOUT = {"calibration": (3, 1), "verification": (3, 1), "transfer": (16, 4)}


def identity(start, rounds):
    return start, tuple(tuple(round_) for round_ in rounds)


def seal(prior_path, target):
    prior_bytes = prior_path.read_bytes()
    prior = json.loads(gzip.decompress(prior_bytes))["panels"]["panels"]
    used = {identity(row["start"], row["operations"]) for panel in prior.values() for level in panel.values()
            for row in level}
    rng = random.Random(SEED)
    panels = {}
    for panel, counts in LAYOUT.items():
        rows = []
        for family, limit in zip(("packing", "register"), counts, strict=True):
            for index in range(limit):
                while True:
                    first, second = rng.sample(range(100, 1000), 2)
                    rounds = operations(rng, 100, 1, 9, 17)
                    gold = [execute(value, rounds) for value in (first, second)]
                    keys = [identity(value, rounds) for value in (first, second)]
                    displayed = {first, second, *rounds[0]}
                    if gold[0] != gold[1] and displayed.isdisjoint(gold) and used.isdisjoint(keys):
                        break
                used.update(keys)
                pair = f"kl.{panel}.{family}.{index}"
                alias = rng.choice(("Aspen", "Cedar", "Elm", "Hazel", "Maple", "Pine"))
                for side, beginning in enumerate((first, second)):
                    rows.append({"id": f"{pair}.{side}", "pair": pair, "side": side, "family": family,
                                 "start": beginning, "operations": rounds, "gold": gold[side],
                                 "question": render(alias, family, beginning, rounds)})
        panels[panel] = rows
    report = {"seed": SEED, "prior_ladder_sha256": hashlib.sha256(prior_bytes).hexdigest(), "panels": panels}
    payload = json.dumps(report, sort_keys=True, separators=(",", ":")).encode() + b"\n"
    with target.open("xb") as stream:
        stream.write(payload)
    print(hashlib.sha256(payload).hexdigest())


if __name__ == "__main__":
    seal(*(Path(value) for value in sys.argv[1:]))

